import { styled } from '@hexa-ui/theme';

export const StyledResourceAllocationSection = styled('div', {
  width: '100%',
  minWidth: 0,

  '& [data-testid="sub-pillar-card"]': {
    width: '100%',
    maxWidth: 'none',
  },

  '& [data-testid="sub-pillar-card-content"]': {
    flexDirection: 'row',
    gap: '16px',
    alignItems: 'stretch',
  },

  '& [data-testid="sub-pillar-card-content"] > *': {
    flex: 1,
    minWidth: 0,
  },
});
